#!/usr/bin/env python3\n\"\"\"\nTest script for dual-mode EID resolution add_triple functionality\nTests both natural language and explicit EID modes\n\"\"\"\n\nimport asyncio\nimport logging\nimport sys\nimport json\nfrom pathlib import Path\n\n# Add src to path for imports\nsys.path.insert(0, str(Path(__file__).parent / \"src\"))\n\ntry:\n    from src.database_manager import DatabaseManager\n    from src.tools.add_triple_tool import AddTripleTool\nexcept ImportError as e:\n    print(f\"❌ Import error: {e}\")\n    print(\"Make sure you're running from the db9-mcp-server directory\")\n    sys.exit(1)\n\n\nasync def test_dual_mode_add_triple():\n    \"\"\"Test our dual-mode EID resolution add_triple functionality\"\"\"\n    print(\"🧠 Testing Dual-Mode EID Resolution Add Triple\")\n    print(\"=\" * 50)\n    \n    # Load config\n    config_path = Path(\"config/default_config.yaml\")\n    if not config_path.exists():\n        print(f\"❌ Config not found: {config_path}\")\n        return False\n    \n    import yaml\n    with open(config_path) as f:\n        config = yaml.safe_load(f)\n    \n    # Initialize components\n    print(\"📊 Initializing database manager...\")\n    db_manager = DatabaseManager(config)\n    \n    # Test connection\n    print(\"🔗 Testing database connection...\")\n    connected = await db_manager.ensure_connected()\n    if not connected:\n        print(\"❌ Database connection failed\")\n        return False\n    \n    print(\"✅ Database connected successfully\")\n    \n    # Initialize add_triple tool\n    print(\"🔧 Initializing AddTripleTool...\")\n    add_tool = AddTripleTool(db_manager)\n    \n    # Test cases for dual-mode EID resolution\n    test_cases = [\n        {\n            \"name\": \"Natural Language Mode\",\n            \"subject\": \"rose_quartz\",\n            \"predicate\": \"has_color\", \n            \"object\": \"pink\",\n            \"validate\": False,\n            \"description\": \"All natural language terms - should auto-create EIDs\"\n        },\n        {\n            \"name\": \"Mixed Mode (Explicit Object)\",\n            \"subject\": \"granite\",\n            \"predicate\": \"contains\",\n            \"object\": \"eid:mineral:quartz_001\",\n            \"validate\": False,\n            \"description\": \"Natural + explicit EID - should resolve appropriately\"\n        },\n        {\n            \"name\": \"Enterprise Mode\",\n            \"subject\": \"eid:rock:granite_001\",\n            \"predicate\": \"eid:relation:mohs_hardness\",\n            \"object\": \"eid:value:hardness_6\",\n            \"validate\": False,\n            \"description\": \"All explicit EIDs - enterprise precision mode\"\n        }\n    ]\n    \n    # Execute test cases\n    for i, test_case in enumerate(test_cases, 1):\n        print(f\"\\n🧪 Test Case {i}: {test_case['name']}\")\n        print(f\"Description: {test_case['description']}\")\n        print(f\"Triple: (\\\"{test_case['subject']}\\\", \\\"{test_case['predicate']}\\\", \\\"{test_case['object']}\\\")\")\n        \n        try:\n            result = add_tool.add_triple(\n                test_case[\"subject\"],\n                test_case[\"predicate\"], \n                test_case[\"object\"],\n                test_case[\"validate\"]\n            )\n            \n            print(\"📋 Result:\")\n            print(json.dumps(result, indent=2))\n            \n            # Analyze result\n            if result[\"status\"] == \"success\":\n                print(\"✅ SUCCESS: Triple added successfully\")\n                if \"resolution_feedback\" in result:\n                    print(\"🔍 EID Resolution Feedback:\")\n                    for role, feedback in result[\"resolution_feedback\"].items():\n                        print(f\"  {role}: {feedback}\")\n            elif result[\"status\"] == \"disambiguation_needed\":\n                print(\"🤔 DISAMBIGUATION: Multiple candidates found\")\n                for role, info in result[\"ambiguous_terms\"].items():\n                    print(f\"  {role} '{info['term']}' has {len(info['candidates'])} candidates\")\n            elif result[\"status\"] == \"entities_not_found\":\n                print(\"❓ MISSING ENTITIES: New entities need creation\")\n                for role, info in result[\"missing_terms\"].items():\n                    print(f\"  {role} '{info['term']}': {info['suggestion']}\")\n            else:\n                print(f\"❌ ERROR: {result.get('message', 'Unknown error')}\")\n                \n        except Exception as e:\n            print(f\"❌ EXCEPTION: {e}\")\n            import traceback\n            traceback.print_exc()\n    \n    # Cleanup\n    await db_manager.disconnect()\n    print(\"\\n🏁 Test completed\")\n    return True\n\n\ndef main():\n    \"\"\"Main test function\"\"\"\n    logging.basicConfig(level=logging.INFO)\n    \n    print(\"🚀 Dual-Mode EID Resolution Test\")\n    print(\"Testing conversational EID resolution with enterprise support\")\n    print()\n    \n    try:\n        success = asyncio.run(test_dual_mode_add_triple())\n        if success:\n            print(\"\\n✅ All tests completed successfully!\")\n            sys.exit(0)\n        else:\n            print(\"\\n❌ Tests failed\")\n            sys.exit(1)\n    except KeyboardInterrupt:\n        print(\"\\n🛑 Test interrupted by user\")\n        sys.exit(1)\n    except Exception as e:\n        print(f\"\\n💥 Test failed with exception: {e}\")\n        import traceback\n        traceback.print_exc()\n        sys.exit(1)\n\n\nif __name__ == \"__main__\":\n    main()\n